-- An identity column added by `ADD COLUMN` is declared `NOT NULL`: a written NULL is refused.
-- @expect-error: null value in a NOT NULL column (23502)
-- @setup
CREATE TABLE aci (v TEXT);
INSERT INTO aci VALUES ('a'), ('b');
ALTER TABLE aci ADD COLUMN id INT GENERATED BY DEFAULT AS IDENTITY;
-- @test
INSERT INTO aci (id, v) VALUES (NULL, 'n');
